create or replace function public.recompute_deep_content_quality_v285_6b(p_topic_id text default null)
returns jsonb
language plpgsql security definer set search_path=public
as $$
declare r record;w int;wc int;g int;gc int;k int;rs int;lab_specs int;mis int;wd int;gd int;ph int;rowsn int:=0;doc text;
begin
 perform public.mathlabs_assert_admin_v22();
 for r in select * from public.deep_learning_paths_v250
   where course_id='cl-6-basico' and content_version='v28.5' and (p_topic_id is null or topic_id=p_topic_id)
 loop
  w:=jsonb_array_length(r.worked_examples);
  select count(*) into wc from jsonb_array_elements(r.worked_examples)e
   where coalesce(e->>'answer','')<>'' and e?'validation_contract'
    and jsonb_array_length(coalesce(e->'steps','[]'::jsonb))>=3
    and coalesce(e->'presentation'->>'interpretation','')<>'';
  g:=jsonb_array_length(r.guided_practice);
  select count(*) into gc from jsonb_array_elements(r.guided_practice)e
   where coalesce(e->>'answer','')<>'' and e?'validation_contract'
    and e->'interaction'->>'validation_rpc'='validate_guided_response_v253';
  select count(*) into k from public.deep_guided_answer_keys_v253
   where topic_id=r.topic_id and validation_type='exact_numeric_or_symbolic'
    and coalesce(expected_text,'')<>'';
  select count(*) into rs from jsonb_array_elements(r.representations)e
   where e->>'render_status'='specification_ready' and e?'payload'
    and coalesce((e->'accessibility'->>'data_table_fallback')::boolean,false);
  select count(*) into lab_specs from jsonb_array_elements(r.interactive_specs)e
   where e->>'implementation_status'='specification_ready'
    and coalesce(e->'student_contract'->>'prediction_prompt','')<>''
    and coalesce(e->'student_contract'->>'interpretation_prompt','')<>'';
  select count(*) into mis from jsonb_array_elements(r.misconceptions)e
   where coalesce(e->>'code','')<>'' and e?'why_plausible' and e?'repair_question';
  select count(*) into wd from (select lower(regexp_replace(btrim(e->>'problem'),'\s+',' ','g')) p,count(*) c from jsonb_array_elements(r.worked_examples)e group by 1 having count(*)>1)d;
  select count(*) into gd from (select lower(regexp_replace(btrim(e->>'problem'),'\s+',' ','g')) p,count(*) c from jsonb_array_elements(r.guided_practice)e group by 1 having count(*)>1)d;
  doc:=to_jsonb(r)::text;
  ph:=(case when doc ilike '%Alternativa no válida%' then 1 else 0 end)
     +(case when doc ~ '(^|[^[:alnum:]_])TBD([^[:alnum:]_]|$)' then 1 else 0 end)
     +(case when doc ilike '%Lorem ipsum%' then 1 else 0 end);

  insert into public.deep_content_quality_v253(
   topic_id,curriculum_score,theory_score,worked_structure_score,guided_interaction_score,
   math_rendering_score,representation_score,lab_score,misconception_transfer_score,total_score,
   worked_examples,structured_worked_examples,guided_practice,interactive_guided_items,
   answer_contracts,spanish_label_items,rendered_math_representations,accessible_representations,
   semantic_labs,prediction_labs,interpretation_labs,student_ready_labs,
   worked_problem_duplicate_groups,guided_problem_duplicate_groups,placeholder_residual,
   human_review_status,interaction_review_status,accessibility_review_status,computed_at
  ) values(r.topic_id,8,9,15,20,15,6,0,5,78,w,wc,g,gc,k,g,0,rs,0,lab_specs,lab_specs,0,wd,gd,ph,'pending','pending','pending',now())
  on conflict(topic_id) do update set curriculum_score=8,theory_score=9,
   worked_structure_score=15,guided_interaction_score=20,math_rendering_score=15,
   representation_score=6,lab_score=0,misconception_transfer_score=5,total_score=78,
   worked_examples=excluded.worked_examples,structured_worked_examples=excluded.structured_worked_examples,
   guided_practice=excluded.guided_practice,interactive_guided_items=excluded.interactive_guided_items,
   answer_contracts=excluded.answer_contracts,spanish_label_items=excluded.spanish_label_items,
   rendered_math_representations=0,accessible_representations=excluded.accessible_representations,
   semantic_labs=0,prediction_labs=excluded.prediction_labs,interpretation_labs=excluded.interpretation_labs,
   student_ready_labs=0,worked_problem_duplicate_groups=excluded.worked_problem_duplicate_groups,
   guided_problem_duplicate_groups=excluded.guided_problem_duplicate_groups,placeholder_residual=excluded.placeholder_residual,
   human_review_status='pending',interaction_review_status='pending',accessibility_review_status='pending',
   reviewer_notes=null,reviewed_by=null,reviewed_at=null,computed_at=now();
  rowsn:=rowsn+1;
 end loop;
 return jsonb_build_object('course_id','cl-6-basico','recomputed',rowsn,'provisional_q4',78,'student_ready',false);
end $$;
revoke all on function public.recompute_deep_content_quality_v285_6b(text) from public,anon,authenticated;
select public.recompute_deep_content_quality_v285_6b(null);

insert into public.curriculum_topic_readiness_v254(
 topic_id,course_id,oa_code,nodes_total,strong_nodes,partial_nodes,gap_nodes,required_nodes,
 required_approved_nodes,human_reviewed_nodes,human_approved_nodes,auto_coverage_score,q4_score,
 q4_student_ready,curriculum_ready,release_candidate,computed_at)
select p.topic_id,'cl-6-basico',(select n.oa_code from public.curriculum_nodes_v254 n where n.topic_id=p.topic_id limit 1),
 4,0,4,0,(select count(*) from public.curriculum_nodes_v254 n where n.topic_id=p.topic_id and n.importance in ('critical','high')),
 0,0,0,85.00,coalesce(q.total_score,0),false,false,false,now()
