insert into public.multigrade_assessment_certification_v264(topic_id,course_id,priority,content_fingerprint)
select p.topic_id,'cl-6-basico',case when right(p.topic_id,1)='a' then 'A' else 'B' end,
 md5(string_agg(i.item_id||'|'||i.stem||'|'||i.options::text||'|'||i.correct_option||'|'||i.solution,'§' order by i.item_id))
from public.deep_learning_paths_v250 p join public.multigrade_assessment_items_v261 i on i.topic_id=p.topic_id
where p.course_id='cl-6-basico' and p.content_version='v28.5' group by p.topic_id;

select public.refresh_v269_course_assessment_readiness('cl-6-basico');

-- Diagnostic preview now derives the valid range from each course blueprint.
create or replace function public.preview_v268_diagnostic(p_course_id text,p_limit int default null)
returns table(item_id text,topic_id text,oa_code text,stem text,difficulty int,depth int)
language plpgsql security definer set search_path=public as $$
declare u uuid:=auth.uid();adm boolean:=false;min_allowed int;target_allowed int;max_allowed int;effective_limit int;
begin
 if u is null then raise exception 'authentication required'; end if;
 select public.is_learning_admin() into adm;
 if not coalesce(adm,false) then raise exception 'admin required'; end if;
 select min_items,target_items,max_items into min_allowed,target_allowed,max_allowed
 from public.multigrade_diagnostic_blueprints_v263
 where course_id=p_course_id and status='staging' order by content_version desc limit 1;
 if min_allowed is null then raise exception 'No diagnostic blueprint for %',p_course_id; end if;
 effective_limit:=coalesce(p_limit,target_allowed);
 if effective_limit<min_allowed or effective_limit>max_allowed then
   raise exception 'p_limit fuera del rango permitido para %: % a %',p_course_id,min_allowed,max_allowed;
 end if;
 return query with ranked as(
  select i.*,m.estimated_seconds,
   row_number() over(partition by i.oa_code order by m.estimated_seconds,i.difficulty,i.item_id) rn
  from public.multigrade_assessment_items_v261 i
  join public.multigrade_adaptive_item_metadata_v262 m using(item_id)
  where i.course_id=p_course_id and i.kind='diagnostic' and i.status='staging' and not i.is_published
 )
 select r.item_id,r.topic_id,r.oa_code,r.stem,r.difficulty,r.depth
 from ranked r order by r.rn,r.oa_code,r.estimated_seconds,r.item_id limit effective_limit;
end $$;
revoke all on function public.preview_v268_diagnostic(text,int) from public,anon,authenticated;
grant execute on function public.preview_v268_diagnostic(text,int) to authenticated;

create or replace function public.get_v289_6b_expansion_overview()
returns jsonb language plpgsql security definer set search_path=public as $$
declare u uuid:=auth.uid();adm boolean:=false;res jsonb;
begin
 if u is null then raise exception 'authentication required'; end if;
 select public.is_learning_admin() into adm;
 if not coalesce(adm,false) then raise exception 'admin required'; end if;
 perform public.refresh_v269_course_assessment_readiness('cl-6-basico');
 select jsonb_build_object(
  'course_id','cl-6-basico',
  'curriculum_snapshot',(select to_jsonb(s) from public.multigrade_curriculum_source_snapshot_v269 s where s.course_id='cl-6-basico'),
  'official_oas',(select count(distinct n.oa_code) from public.curriculum_nodes_v254 n join public.deep_learning_paths_v250 p on p.topic_id=n.topic_id where p.course_id='cl-6-basico' and p.content_version='v28.5'),
  'deep_topics',(select count(*) from public.deep_learning_paths_v250 where course_id='cl-6-basico' and content_version='v28.5'),
  'curriculum_nodes',(select count(*) from public.curriculum_nodes_v254 where course_id='cl-6-basico' and is_active),
  'micro_lessons',(select sum(jsonb_array_length(micro_lessons)) from public.deep_learning_paths_v250 where course_id='cl-6-basico' and content_version='v28.5'),
  'worked_examples',(select sum(jsonb_array_length(worked_examples)) from public.deep_learning_paths_v250 where course_id='cl-6-basico' and content_version='v28.5'),
  'guided_practice',(select sum(jsonb_array_length(guided_practice)) from public.deep_learning_paths_v250 where course_id='cl-6-basico' and content_version='v28.5'),
  'practice',(select count(*) from public.multigrade_assessment_items_v261 where course_id='cl-6-basico' and kind='practice'),
  'diagnostic',(select count(*) from public.multigrade_assessment_items_v261 where course_id='cl-6-basico' and kind='diagnostic'),
  'review',(select count(*) from public.multigrade_assessment_items_v261 where course_id='cl-6-basico' and kind='review'),
  'review_sets',(select count(*) from public.multigrade_review_sets_v261 where course_id='cl-6-basico'),
  'adaptive_metadata',(select count(*) from public.multigrade_adaptive_item_metadata_v262 where course_id='cl-6-basico'),
  'heuristic_metadata',(select count(*) from public.multigrade_adaptive_item_metadata_v262 where course_id='cl-6-basico' and calibration_status='heuristic_candidate'),
  'calibrated_metadata',(select count(*) from public.multigrade_adaptive_item_metadata_v262 where course_id='cl-6-basico' and calibration_status='calibrated'),
  'diagnostic_blueprints',(select count(*) from public.multigrade_diagnostic_blueprints_v263 where course_id='cl-6-basico'),
  'route_contracts',(select count(*) from public.multigrade_learning_route_contract_v264 where course_id='cl-6-basico'),
  'auto_gate_topics',(select count(*) from public.multigrade_assessment_readiness_v264 where course_id='cl-6-basico' and auto_gate_pass),
  'human_certified_topics',(select count(*) from public.multigrade_assessment_certification_v264 where course_id='cl-6-basico' and certified),
  'release_candidates',(select count(*) from public.multigrade_assessment_readiness_v264 where course_id='cl-6-basico' and release_candidate),
  'published_deep_topics',(select count(*) from public.deep_learning_paths_v250 where course_id='cl-6-basico' and status='published'),
  'published_assessment_items',(select count(*) from public.multigrade_assessment_items_v261 where course_id='cl-6-basico' and is_published),
  'live_student_delivery',(select live_student_delivery from public.multigrade_course_runtime_gate_v269 where course_id='cl-6-basico'),
  'topics',coalesce((select jsonb_agg(jsonb_build_object('topic_id',r.topic_id,'practice',r.practice_items,
   'diagnostic',r.diagnostic_items,'review',r.review_items,'metadata',r.adaptive_metadata_rows,'q4',r.q4_score,
   'auto_gate',r.auto_gate_pass,'human_certified',r.human_certified,'release_candidate',r.release_candidate,
   'blockers',r.blocker_codes,'priority',c.priority) order by c.priority,r.topic_id)
   from public.multigrade_assessment_readiness_v264 r join public.multigrade_assessment_certification_v264 c using(topic_id)
   where r.course_id='cl-6-basico'),'[]'::jsonb)
 ) into res;
 return res;
end $$;
revoke all on function public.get_v289_6b_expansion_overview() from public,anon,authenticated;
grant execute on function public.get_v289_6b_expansion_overview() to authenticated;

update public.mathlabs_course_catalog_v259 set lifecycle_status='staging',content_version='v28.5',updated_at=now() where course_id='cl-6-basico';
update public.mathlabs_course_import_contract_v259 set curriculum_import_status='validated',expected_oa_count=24,expected_topic_count=48,
 source_reference='Currículum Nacional · Matemática 6.º básico · snapshot 2026-08-12',
 next_action='6B staging completo v28.5-v28.9. Revalidar currículo, revisar contenido, certificar y calibrar antes de release.',updated_at=now()
where course_id='cl-6-basico';
update public.mathlabs_course_module_readiness_v259 set readiness_status=case module_key
 when 'curriculum_map' then 'ready' when 'deep_learning' then 'staging' when 'worked_guided' then 'staging'
 when 'representations' then 'staging' when 'practice_bank' then 'staging' when 'diagnostic' then 'staging'
 when 'review' then 'staging' when 'adaptive_engine' then 'partial' when 'content_certification' then 'planned'
 when 'interaction_certification' then 'planned' when 'release_governance' then 'planned' else readiness_status end,
 details=details||jsonb_build_object('v28.5_v28.9',true,'content_version','v28.5','assessment_version','v28.6',
 'curriculum_snapshot','2026-08-12','live_student_delivery',false,'curriculum_revalidation_before_release',true),refreshed_at=now()
where course_id='cl-6-basico';

create or replace function public.refresh_v259_course_architecture()
returns jsonb language plpgsql security definer set search_path=public as $$
declare r record;tp int;nd int;ml int;we int;gp int;rr int;pi int;di int;ri int;mr int;mt int;score numeric;blocks jsonb;rowsn int:=0;
begin
 perform public.mathlabs_assert_admin_v22();
 for r in select * from public.mathlabs_course_catalog_v259 order by sequence_order loop
   select count(*),coalesce(sum(jsonb_array_length(micro_lessons)),0),coalesce(sum(jsonb_array_length(worked_examples)),0),
    coalesce(sum(jsonb_array_length(guided_practice)),0),coalesce(sum((select count(*) from jsonb_array_elements(representations)x where x->>'render_status'='rendered')),0)
   into tp,ml,we,gp,rr from public.deep_learning_paths_v250 where course_id=r.course_id and status<>'retired';
   select count(*) into nd from public.curriculum_nodes_v254 where course_id=r.course_id and is_active;
   pi:=0;di:=0;ri:=0;
   if exists(select 1 from public.multigrade_assessment_items_v261 where course_id=r.course_id) then
     select count(*) filter(where kind='practice'),count(*) filter(where kind='diagnostic'),count(*) filter(where kind='review')
     into pi,di,ri from public.multigrade_assessment_items_v261 where course_id=r.course_id;
   elsif r.course_id='cl-4-medio' then
     select count(*) into pi from public.school_practice_items where code like '4M-V225-P-%' and is_published;
     select count(*) into di from public.school_diagnostic_items where diagnostic_version='4m-fg-v225' and is_published;
     select count(*) into ri from public.school_review_items where code like '4M-V225-R-%' and is_published;
   end if;
   select count(*),count(*) filter(where readiness_status in ('ready','staging','production')) into mt,mr
   from public.mathlabs_course_module_readiness_v259 where course_id=r.course_id;
   score:=case when mt=0 then 0 else round(100.0*mr/mt,2) end;
   blocks:='[]'::jsonb;
   if tp=0 then blocks:=blocks||'"CONTENT_NOT_BUILT"'::jsonb; end if;
   if exists(select 1 from public.multigrade_course_runtime_gate_v269 g where g.course_id=r.course_id) then
     select blocker_codes into blocks from public.multigrade_course_runtime_gate_v269 where course_id=r.course_id;
   elsif r.course_id='cl-4-medio' then blocks:=blocks||'"V25_HUMAN_CERTIFICATION_PENDING"'::jsonb; end if;
   insert into public.mathlabs_course_architecture_snapshot_v259(
    course_id,topics,curriculum_nodes,micro_lessons,worked_examples,guided_practice,rendered_representations,
    practice_items,diagnostic_items,review_items,modules_ready,modules_total,architecture_readiness,
    student_release_candidate,blocker_codes,refreshed_at)
   values(r.course_id,tp,nd,ml,we,gp,rr,pi,di,ri,mr,mt,score,false,blocks,now())
   on conflict(course_id) do update set topics=excluded.topics,curriculum_nodes=excluded.curriculum_nodes,
    micro_lessons=excluded.micro_lessons,worked_examples=excluded.worked_examples,guided_practice=excluded.guided_practice,
    rendered_representations=excluded.rendered_representations,practice_items=excluded.practice_items,
    diagnostic_items=excluded.diagnostic_items,review_items=excluded.review_items,modules_ready=excluded.modules_ready,
    modules_total=excluded.modules_total,architecture_readiness=excluded.architecture_readiness,student_release_candidate=false,
    blocker_codes=excluded.blocker_codes,refreshed_at=now();
   rowsn:=rowsn+1;
 end loop;
 return jsonb_build_object('registered_courses',rowsn,'active_expansion','cl-6-basico','macroblock','v28.5-v28.9');
end $$;
revoke all on function public.refresh_v259_course_architecture() from public,anon,authenticated;
select public.refresh_v259_course_architecture();

commit;
